 form.onsubmit=event=>{event.preventDefault();void(async()=>{submit.disabled=true;error.textContent='';try{if(jobId!==reviewJobId||version!==reviewData.version)throw new Error('Reload the current translation.');const answers=[...body.querySelectorAll('input')].map(input=>({context:input.dataset.context,answer:input.value}));if(preview.questions.length){preview=await localRequest(`/api/jobs/${jobId}/review/rules`,{action:'check',previewId:preview.previewId,version,answers}).then(response=>response.json());render();return;}reviewSubmitting=true;renderReviewControls();const result=await localRequest(`/api/jobs/${jobId}/review/edit`,{rulePreviewId:preview.previewId,version,requestId,locale:locale()}).then(response=>response.json());if(result.rulePreview){preview=result.rulePreview;render();return;}dialog.close();renderReview(result);await loadReview(true);}catch(err){error.textContent=err.message;}finally{submit.disabled=false;reviewSubmitting=false;renderReviewControls();update();}})();};
 window.TOCRRuleApplication={update};window.addEventListener('translateocr-locale',()=>{update();if(preview&&dialog.open)render();});update();
